import { useCallback, useState } from 'react';

import OpenFin from '@openfin/core';

import { createLogger } from '@common/utils/logger';
import { menuEvents } from '@common/utils/menu-window-provider';
import {
    BasePopupMenuChannelMessage,
    ContextMenuChannelMessage,
    PopupWindowMenuType,
    RenameSupertabChannelMessage
} from '@common/utils/popup-window';
import { configurePopupParentIdentityLifecycle } from '@common/utils/popup-window/parentIdentityLifecycle';
import { usePopupChannel } from '@common/utils/popup-window/usePopupChannel';
import { getCurrentOFWindow } from '@common/utils/window';

import { useIsWindows } from './useIsWindows';

const logger = createLogger('common.useManagePopupWindow');

export type ContextMenuWindowMessage = ContextMenuChannelMessage | RenameSupertabChannelMessage;

const getResponseTopic = (payload: BasePopupMenuChannelMessage) => {
    const shouldTargetRequestId =
        'requestId' in payload &&
        (payload.type === PopupWindowMenuType.ContextMenu || payload.type === PopupWindowMenuType.GlobalMenu);

    // Context menu invocations coming from the provider window should target a topic with a specific requestId.
    return shouldTargetRequestId ? `response-${payload.requestId}` : 'response';
};

interface UseManagePopupWindowOptions {
    blurBehavior?: 'hide' | 'modal';
    dispatchDirectlyToChannel?: boolean;
    forwardTopicName?: string;
}

/*
 * This hook is used to manage the popup window state and show the popup window.
 * @param windowName - The name of the popup window.
 * @param createChannel - The function to create the channel.
 * @param showPopupOverride - The function to show the popup window. If not provided, the default behavior will be used to show the popup window.
 * @param options - An object containing optional parameters.
 * @param options.blurBehavior - The behavior of the popup window when it loses focus. Can be 'hide' or 'modal'. Defaults to 'hide'.
 * @param options.dispatchDirectlyToChannel - If true, the response will be dispatched directly to the channel. If false, the response will be dispatched to the parent window.
 * @param options.forwardTopicName - The topic name to forward the response to.
 */
export const useManagePopupWindow = <T extends BasePopupMenuChannelMessage>(
    windowName: string,
    createChannel: () => Promise<OpenFin.ChannelProvider>,
    showPopupOverride?: (bounds: OpenFin.Bounds, message?: T) => Promise<void>,
    options?: UseManagePopupWindowOptions
) => {
    const [payload, setPayload] = useState<T | null>(null);

    const isWindows = useIsWindows();

    const handlePopupRequest = useCallback(async (ev: T) => {
        const window = fin.me as OpenFin.Window;

        // Assuming a popup window is currently active, if a user attempts to activate the popup window elsewhere, we want to
        // first blur the popup window to emit a response for the first invocation before setting the payload to re-show.
        if (await window.isShowing()) {
            await window.blur();
        }
        setPayload(ev);
    }, []);

    const channelToParent = usePopupChannel<T>({
        createChannel,
        actionName: 'open',
        handler: handlePopupRequest
    });

    // compute inline instead of adding as deps below to avoid re-computing the callbacks
    const blurBehavior = options?.blurBehavior ?? 'hide';
    const dispatchDirectlyToChannel = !!options?.dispatchDirectlyToChannel;
    const forwardTopicName = options?.forwardTopicName;

    const showPopup = useCallback(
        async (bounds: OpenFin.Bounds) => {
            if (!payload) return;

            menuEvents.emit('modal-opened', windowName);

            const popupWindow = fin.Window.wrapSync({ name: windowName, uuid: fin.me.uuid });
            const parentWindow = fin.Window.wrapSync(payload.parentIdentity);
            await configurePopupParentIdentityLifecycle(popupWindow, payload.parentIdentity, isWindows);

            if (showPopupOverride) {
                await showPopupOverride(bounds, payload);
                return;
            }

            try {
                const { height, width, top, left } = bounds;

                (fin.me as OpenFin.Window).once('blurred', () => setPayload(null));
                const response = await parentWindow.showPopupWindow({
                    name: windowName,
                    resultDispatchBehavior: 'hide',
                    blurBehavior,
                    hideOnClose: true,
                    focus: true,
                    height,
                    width,
                    x: left,
                    y: top,
                    additionalOptions: {
                        alwaysOnTop: true,
                        contextMenuOptions: {
                            enabled: true,
                            template: ['inspect']
                        }
                    }
                });

                const responseTopic = getResponseTopic(payload);
                await channelToParent.current?.dispatch(payload.responseIdentity, responseTopic, response);

                if (forwardTopicName) {
                    channelToParent.current?.publish(forwardTopicName, response);
                }
            } catch (error) {
                logger.error('showPopup', 'Error showing popup', {
                    error: error instanceof Error ? error.message : String(error)
                });
            }
        },
        [payload, showPopupOverride, windowName, blurBehavior, forwardTopicName, channelToParent, isWindows]
    );

    const onResponse = useCallback(
        async (data?: any) => {
            try {
                if (dispatchDirectlyToChannel) {
                    if (payload) {
                        await channelToParent.current?.dispatch(payload.responseIdentity, 'response', data);

                        if (forwardTopicName) {
                            Promise.all(channelToParent.current?.publish(forwardTopicName, data)).catch(() => {
                                /* Channel that listens to forwarding messages is not open */
                            });
                        }
                    }

                    if (data.type === 'cancel' || data.type === 'dropdown-blurred') {
                        setPayload(null);
                    }
                } else {
                    await getCurrentOFWindow().dispatchPopupResult(data);

                    if (payload) {
                        setPayload(null);
                    }
                }
            } catch (error) {
                logger.error('onResponse', 'Error handling response', {
                    error: error instanceof Error ? error.message : String(error)
                });
            }
        },
        [payload, dispatchDirectlyToChannel, forwardTopicName, channelToParent]
    );

    return {
        channelRef: channelToParent,
        payload,
        showPopup,
        onResponse
    };
};
